INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370022, 15492, 'The Times of India', 'en', '''Take Gyanesh Kumar to US'': Cong''s jibe after Trump praises India''s poll system', 'https://timesofindia.indiatimes.com/india/please-take-gyanesh-kumar-to-america-congresss-jibe-at-cec-after-trump-lauds-indian-electoral-system/articleshow/133314095.cms', 'Congress spokesperson Pawan Khera took aim at Chief Election Commissioner Gyanesh Kumar''s views on US voter identification rules, highlighting a comment made by Donald Trump that praised India''s election system. With a hint of sarcasm, Khera proposed sending India’s electronic voting machines and Kumar to the US. This debate highlights ongoing tensions between Congress and the Election Commission, particularly regarding accusations of vote theft during past Lok Sabha elections.', 'https://static.toiimg.com/photo/msid-133314156,imgsize-69979.cms', '2026-08-18T06:48:58+00:00', '2026-08-18T07:26:42.737929'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
