INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370182, 15492, 'The Telegraph (India)', 'en', '‘Please take Gyanesh Kumar to America’: Pawan Khera’s message to Trump over India’s election system', 'https://news.google.?oc=5', '‘Please take Gyanesh Kumar to America’: Pawan Khera’s message to Trump over India’s election system Telegraph India', '', '2026-08-18T06:48:27+00:00', '2026-08-18T07:28:11.611268'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (370512, 15492, 'South China Morning Post', 'en', 'Trump leans on India’s election playbook in push to change how Americans vote', 'https://www.scmp.com/news/world/united-states-canada/article/3364400/trump-leans-indias-election-playbook-push-change-how-americans-vote', 'US President Donald Trump cited India’s election system as a model for the US, bringing the world’s largest democracy into a contentious American debate over voter access and election security. Trump said the identification requirements make elections secure and pressed Congress to pass the SAVE America Act, which would require proof of citizenship to register for federal elections and photo identification to vote. The measure has stalled in the Senate as Trump and his Republican allies push for...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/4f435e6c-3941-4bc9-8a18-98eebe2d31a9_408b6757.jpg?itok=6Aly8Ltx&v=1787035794', '2026-08-18T06:49:55+00:00', '2026-08-18T07:33:19.442104'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
