INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365008, 15544, 'The Times of India', 'en', 'Gen Alpha, Gen Z students march in Lucknow over shortage of teachers, amenities', 'https://timesofindia.indiatimes.com/city/lucknow/schoolgirls-lay-siege-to-road-to-protest-shortage-of-teachers-amenities/articleshow/133305868.cms', 'Students protested teacher shortages and poor school amenities on Monday. They walked 2.5km to the bypass, demanding immediate teacher appointments. The residential school students worried about upcoming board exams due to few classes. Police intervened after the protest disrupted traffic and moved towards Hazratganj. Senior officials resolved the situation by listening to student grievances.', 'https://static.toiimg.com/photo/msid-133310109,imgsize-275430.cms', '2026-08-17T19:09:45+00:00', '2026-08-18T03:05:23.616435'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
