INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372553, 15544, 'The Times of India', 'en', 'No chemistry teacher: Gen alpha students protest at Azamgarh school', 'https://timesofindia.indiatimes.com/city/lucknow/our-future-is-burning-like-acid-gen-alpha-students-protest-fee-hike-chemistry-teacher-shortage-at-azamgarh-school/articleshow/133315473.cms', 'Students protested their Azamgarh college, citing excessive fees and teacher shortages. They demanded a chemistry teacher, receiving assurances of one within forty-eight hours. Allegations of unreturned funds and management issues were also raised by supporters. The students seek fair treatment and better academic facilities from the institution. They warned of renewed protests if the chemistry teacher is not provided promptly.', 'https://static.toiimg.com/photo/msid-133315527,imgsize-140742.cms', '2026-08-18T07:48:48+00:00', '2026-08-18T10:04:15.931179'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
